原文示意代码可整理为：
```cpp
string guestName;
int partySize{0};
char ch;
cin >> noskipws;
while (true) {
    ch = static_cast<char>(cin.peek());
    if (!cin) break;
    if (isdigit(ch)) break;
    cin >> ch;
    if (!cin) break;
    guestName += ch;
}
if (cin) cin >> partySize;
if (!cin) {
    cerr << "Error getting party size." << endl;
    return;
}
cout << format("Thank you '{}', party of {}", guestName, partySize) << endl;
```
